  V.rateForm=mid=>{const m=db.member(mid);V.open(`<h3>تقييم ${esc(m.name)}</h3>${['اللياقة','التحكم والمهارة','التمرير','التسديد','الدفاع والتمركز'].map((n,i)=>field('vk-'+i,n,select('vk-'+i,[1,2,3,4,5].map(v=>[String(v),String(v)]),String(m.skill[i])))).join('')}${field('vk-note','ملاحظة للاعب','<textarea id="vk-note" rows="3"></textarea>')}${button('حفظ التقييم',`V.rateSave('${mid}')`)}`);};
