  V.captureCoach=()=>{if(!mobile||db.error)return;const s=current(),snapshot=JSON.stringify([C.teams||null,C.rec||null]);if(coachSnapshotSession===s.id&&coachSnapshot===snapshot)return;const [teams,record]=JSON.parse(snapshot);db.update(()=>{s.teams=teams;s.record=record;});coachSnapshot=snapshot;coachSnapshotSession=s.id;};
