  V.shifts=()=>`${title('إقفال الوردية')}<div class="v-summary"><div class="v-eyebrow">كاش الوردية الحالية</div><div class="v-number">${money(db.cashExpected())}</div>${button('مراجعة وتسليم الوردية','V.open(V.shiftForm())')}</div>${db.state.shifts.map(s=>`<div class="v-request"><b>${stamp(s.at)}</b><p>المتوقع ${money(s.expected)} · الفعلي ${money(s.actual)}</p><p class="${s.difference?'v-due':''}">الفرق ${money(s.difference)}</p><p>${esc(s.note)}</p></div>`).join('')||empty('مفيش ورديات مقفولة','عمليات الكاش الجديدة هتدخل في الوردية الحالية.')}`;
  V.newMemberForm=(leadId='')=>{const l=db.state.leads.find(l=>l.id===leadId);return `<h3>عضو جديد</h3>${field('vn-name','الاسم',input('vn-name','text',l?.name||''))}${field('vn-phone','رقم الموبايل',input('vn-phone','tel',l?.phone||'','dir="ltr" autocomplete="tel"'))}${field('vn-group','الجروب',select('vn-group',db.state.groups.map(g=>[g.id,g.name]),'A'))}<div class="v-note">هيتم إنشاء ملف بدون اشتراك نشط. الخطوة التالية اختيار الباقة وتحصيل المبلغ.</div>${button('حفظ العضو والانتقال للتحصيل',`V.newMemberSave('${leadId}')`)}`;};
  V.newMemberSave=leadId=>V.run(()=>{const m=db.addMember({name:val('vn-name'),phone:val('vn-phone'),group:val('vn-group')});V.sync();render();V.open(V.collectForm(m.id));});
  V.members=()=>`${title('الأعضاء')}<div class="v-inline"><input class="v-search" aria-label="بحث بالاسم أو الموبايل" placeholder="الاسم أو الموبايل" value="${esc(V.memberQuery)}" oninput="V.filterMembers(this.value)">${button('عضو جديد','V.open(V.newMemberForm())')}</div><div id="v-members-list">${V.memberRows()}</div>`;
