  V.leadSave=()=>V.run(()=>{if(!val('vl-owner')||!val('vl-due'))throw Error('حدد مسؤول وموعد المتابعة');db.saveLead({name:val('vl-name'),phone:val('vl-phone'),source:val('vl-source'),owner:val('vl-owner'),due:val('vl-due')});V.close();render();});
